// ---- _shared/auth.ts -----------------------------------------
// Shared caller authentication for edge functions (Phase 0, SEC-01).
//
// Rule (docs/cpo/09-security-baseline.md §2): a function derives tenant access
// from a VERIFIED credential, never from a header or body. For calls made by a
// signed-in app user, the safest pattern is to act AS that user: queries run
// through a client carrying the user's JWT, so Postgres RLS enforces tenant
// isolation even if function code has a bug. Use the service role only after
// authentication, and only for work RLS can't express.


class AuthError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

type AuthedUser = {
  userId: string;
  email: string | null;
  /** Client that runs every query as the caller — RLS applies. */
  db: SupabaseClient;
};

const AUTH_UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function requireEnv(name: string): string {
  const v = Deno.env.get(name);
  if (!v) throw new AuthError(500, `Server misconfigured: ${name} is not set`);
  return v;
}

/** Verify the bearer token belongs to a real signed-in user (not the anon key). */
async function authenticateUser(req: Request): Promise<AuthedUser> {
  const header = req.headers.get('authorization') ?? '';
  const token = header.startsWith('Bearer ') ? header.slice(7).trim() : '';
  if (!token) throw new AuthError(401, 'Not signed in');

  const db = createClient(requireEnv('SUPABASE_URL'), requireEnv('SUPABASE_ANON_KEY'), {
    global: { headers: { Authorization: `Bearer ${token}` } },
    auth: { persistSession: false, autoRefreshToken: false },
  });

  // getUser validates signature + expiry with Auth; the anon key has no user and fails here.
  const { data, error } = await db.auth.getUser(token);
  if (error || !data?.user) throw new AuthError(401, 'Session is invalid or expired');

  return { userId: data.user.id, email: data.user.email ?? null, db };
}

/** Confirm the caller is an active member of the tenant (checked by the database as the caller). */
async function requireTenantMember(user: AuthedUser, tenantId: unknown): Promise<string> {
  if (typeof tenantId !== 'string' || !AUTH_UUID_RE.test(tenantId)) throw new AuthError(400, 'tenant_id must be a UUID');
  const { data, error } = await user.db.rpc('user_has_tenant_access', { p_tenant_id: tenantId });
  if (error) {
    console.error('tenant membership check failed', error.message);
    throw new AuthError(500, 'Could not verify tenant access');
  }
  if (data !== true) throw new AuthError(403, 'No access to this tenant');
  return tenantId.toLowerCase();
}

/** Tenant named by the caller (membership verified), or the caller's own active membership. */
async function resolveTenant(user: AuthedUser, tenantId: unknown): Promise<string> {
  if (tenantId !== undefined && tenantId !== null && tenantId !== '') return requireTenantMember(user, tenantId);
  const { data, error } = await user.db.from('tenant_users').select('tenant_id')
    .eq('user_id', user.userId).eq('status', 'active').order('created_at').limit(1);
  if (error) throw new AuthError(500, 'Could not resolve your workspace');
  const t = data?.[0]?.tenant_id as string | undefined;
  if (!t) throw new AuthError(403, 'You are not a member of any workspace');
  return t;
}

/** Throws 403 unless the caller holds `permission` in the tenant (tenant admins hold all). */
async function requirePermission(user: AuthedUser, tenantId: string, permission: string, label?: string): Promise<void> {
  const { data, error } = await user.db.rpc('user_has_permission', { p_tenant_id: tenantId, p_permission: permission });
  if (error) throw new AuthError(500, 'Could not verify permissions');
  if (data !== true) throw new AuthError(403, `You need the "${label ?? permission}" permission for this`);
}

// ---- _shared/webhook-sig.ts ----------------------------------
// Constant-time compare + HMAC signature verification (Phase 0 · SEC-18).
// No imports, so it is easy to test and safe to share.

function constantTimeEqual(a: string, b: string): boolean {
  const ea = new TextEncoder().encode(a);
  const eb = new TextEncoder().encode(b);
  let diff = ea.length ^ eb.length;
  for (let i = 0; i < Math.max(ea.length, eb.length); i += 1) diff |= (ea[i] ?? 0) ^ (eb[i] ?? 0);
  return diff === 0;
}

/** HMAC-SHA* of `body` (the exact raw bytes received) with `secret`, as lowercase hex and base64. */
async function hmacDigests(secret: string, body: string | Uint8Array, algorithm: string): Promise<{ hex: string; b64: string }> {
  const algo = algorithm.toUpperCase();
  const hash = algo === 'SHA512' ? 'SHA-512' : algo === 'SHA1' ? 'SHA-1' : 'SHA-256';
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(secret), { name: 'HMAC', hash }, false, ['sign']);
  const bytes: Uint8Array<ArrayBuffer> = typeof body === 'string' ? new TextEncoder().encode(body) : new Uint8Array(body);
  const sig = new Uint8Array(await crypto.subtle.sign('HMAC', key, bytes));
  const hex = Array.from(sig, (b) => b.toString(16).padStart(2, '0')).join('');
  let bin = '';
  for (const b of sig) bin += String.fromCharCode(b);
  return { hex, b64: btoa(bin) };
}

/**
 * Verify a webhook signature header. Accepts bare hex, bare base64, or
 * "<algo>=<hex>" (e.g. GitHub's "sha256=…"). Constant-time compare.
 */
async function verifyHmacSignature(secret: string, body: string | Uint8Array, algorithm: string, provided: string): Promise<boolean> {
  if (!secret || !provided) return false;
  const value = provided.trim().replace(/^(sha1|sha256|sha512)=/i, '');
  const { hex, b64 } = await hmacDigests(secret, body, algorithm);
  return constantTimeEqual(value.toLowerCase(), hex) || constantTimeEqual(value, b64);
}

// ---- _shared/tenant-guard.ts ---------------------------------
// Workspace guards for edge functions that act with the service role
// (Phase 0 · TD-12b, SEC-18).
//
// sql/91 makes suspension automatic for anything that goes through RLS or the
// permission helpers. Functions that use the service role and find the tenant
// themselves (a form id, a bot id, a webhook path, an asset id) must call
// assertTenantActive() once they know the tenant. All checks fail CLOSED: if the
// database can't answer, the request is refused.


/** True only if the tenant exists and is not suspended. */
async function tenantIsActive(service: SupabaseClient, tenantId: string): Promise<boolean> {
  const { data, error } = await service.rpc('tenant_is_active', { p_tenant_id: tenantId });
  if (error) {
    console.error('tenant_is_active failed', error.message);
    throw new AuthError(503, 'Workspace check unavailable — try again shortly');
  }
  return data === true;
}

/** Throws 403 "This workspace is suspended" (or 503 if the check can't run). */
async function assertTenantActive(service: SupabaseClient, tenantId: string): Promise<void> {
  if (!(await tenantIsActive(service, tenantId))) throw new AuthError(403, 'This workspace is suspended');
}

/** True when the caller presented the project's service-role key (internal engine calls). */
function isServiceCaller(req: Request): boolean {
  const key = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';
  const header = req.headers.get('authorization') ?? '';
  const token = header.startsWith('Bearer ') ? header.slice(7).trim() : '';
  return key.length > 0 && token.length > 0 && constantTimeEqual(token, key);
}

/**
 * Signed-in user who is an ACTIVE member of an ACTIVE tenant and holds one of
 * `permissions` (tenant admins hold all). Returns the user id; throws AuthError.
 */
async function requireMemberWithPermission(
  service: SupabaseClient,
  req: Request,
  tenantId: string,
  permissions: string[],
): Promise<string> {
  const header = req.headers.get('authorization') ?? '';
  const token = header.startsWith('Bearer ') ? header.slice(7).trim() : '';
  if (!token) throw new AuthError(401, 'Not signed in');
  const { data, error } = await service.auth.getUser(token);
  if (error || !data?.user) throw new AuthError(401, 'Session is invalid or expired');
  for (const permission of permissions) {
    const { data: ok, error: permErr } = await service.rpc('user_has_permission_as', {
      p_user_id: data.user.id, p_tenant_id: tenantId, p_permission: permission,
    });
    if (permErr) {
      console.error('user_has_permission_as failed', permErr.message);
      throw new AuthError(503, 'Permission check unavailable — try again shortly');
    }
    if (ok === true) return data.user.id;
  }
  throw new AuthError(403, 'You do not have permission for this in this workspace');
}

// ---- _shared/secret-box.ts -----------------------------------
// Server-side secret sealing (Phase 0 · SEC-05/SEC-07).
//
// Seals tenant secrets (AI provider keys, global-variable secrets) with AES-256-GCM
// using ONE server-only master key: the edge-function secret MARBEE_SECRETS_KEY
// (32 random bytes, base64). The database only ever stores the sealed envelope:
//
//     mbs1.<base64 12-byte IV>.<base64 ciphertext+tag>
//
// The browser never sees the master key or the plaintext. Values written before this
// existed are plaintext ("legacy"); openSecret() still returns them so nothing breaks,
// and callers re-seal them on next use.
//
// Generate a key:  node -e "console.log(require('crypto').randomBytes(32).toString('base64'))"
// Set it:          Supabase Dashboard → Edge Functions → Secrets → MARBEE_SECRETS_KEY

const PREFIX = 'mbs1';
const enc = new TextEncoder();
const dec = new TextDecoder();

let cachedKey: CryptoKey | null = null;
let cachedFrom: string | null = null;

function b64(bytes: Uint8Array): string {
  let s = '';
  for (let i = 0; i < bytes.length; i += 1) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}
function unb64(s: string): Uint8Array<ArrayBuffer> {
  const bin = atob(s);
  const out = new Uint8Array(new ArrayBuffer(bin.length));
  for (let i = 0; i < bin.length; i += 1) out[i] = bin.charCodeAt(i);
  return out;
}

function readMasterKey(): string {
  // deno-lint-ignore no-explicit-any
  const env = (globalThis as any).Deno?.env;
  const v = env?.get('MARBEE_SECRETS_KEY')?.trim();
  if (!v) throw new Error('Server misconfigured: MARBEE_SECRETS_KEY is not set');
  return v;
}

async function masterKey(): Promise<CryptoKey> {
  const material = readMasterKey();
  if (cachedKey && cachedFrom === material) return cachedKey;
  const raw = unb64(material);
  if (raw.length !== 32) throw new Error('MARBEE_SECRETS_KEY must be 32 bytes (base64)');
  cachedKey = await crypto.subtle.importKey('raw', raw, { name: 'AES-GCM' }, false, ['encrypt', 'decrypt']);
  cachedFrom = material;
  return cachedKey;
}

function isSealed(value: string | null | undefined): boolean {
  return typeof value === 'string' && value.startsWith(`${PREFIX}.`);
}

/** Encrypt a secret for storage. */
async function sealSecret(plaintext: string): Promise<string> {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, await masterKey(), enc.encode(plaintext)));
  return `${PREFIX}.${b64(iv)}.${b64(ct)}`;
}

/** Decrypt a stored secret. Legacy plaintext is returned as-is; empty → null. Tampered → throws. */
async function openSecret(stored: string | null | undefined): Promise<string | null> {
  if (stored === null || stored === undefined) return null;
  const v = stored.trim();
  if (!v) return null;
  if (!isSealed(v)) return v; // legacy plaintext — caller should re-seal
  const [, ivB64, ctB64] = v.split('.');
  if (!ivB64 || !ctB64) throw new Error('Malformed sealed secret');
  const pt = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: unb64(ivB64) }, await masterKey(), unb64(ctB64));
  return dec.decode(pt);
}

/** "…abcd" for display. Never reveals more than the last 4 characters. */
function last4(plaintext: string): string {
  const t = plaintext.trim();
  return t.length <= 4 ? '' : t.slice(-4);
}

// ---- _shared/web-push.ts -------------------------------------
// Web Push over Firebase Cloud Messaging HTTP v1 (D-022).
//
// Shared by channel-send (tests + real-time sends) and push-worker (campaign/journey
// outbox). Pure pieces — service-account parsing, message building, response
// classification — are unit-tested in supabase/tests/functions/web-push.test.mjs.
//
// Messages are DATA-ONLY: the Marbee service worker (public/sdk/v1/marbee-push-sw.js)
// always draws the notification itself, so there is never a second, auto-drawn copy.

type ServiceAccount = {
  type?: string;
  project_id: string;
  client_email: string;
  private_key: string;
  token_uri?: string;
};

type PushAction = { action?: string; title?: string; url?: string };

/** What a send carries. Everything here ends up visible on the device — no secrets. */
type PushContent = {
  title: string;
  body?: string;
  icon_url?: string;
  image_url?: string;
  badge_url?: string;
  tag?: string;
  click_url?: string;
  ttl_seconds?: number;
  actions?: PushAction[];
  track_clicks?: boolean;
  /** Keep the notification on screen until the user acts on it (Chrome/Edge desktop). */
  require_interaction?: boolean;
};

type PushContext = {
  message_id: string;
  tenant_id: string;
  environment: string;
  journey_id?: string | null;
  delivery_id?: string | null;
  delivery_name?: string | null;
  /** Full URL of the push-engage function, so the service worker can report clicks. */
  engage_url?: string;
};

type SendOutcome = 'delivered' | 'retry' | 'invalid_token' | 'failed';
type SendResult = { outcome: SendOutcome; error?: string; retryAfterSeconds?: number; httpStatus?: number };

function parseServiceAccount(raw: string): ServiceAccount {
  let sa: Partial<ServiceAccount>;
  try {
    sa = JSON.parse(raw);
  } catch {
    throw new Error('Service account JSON is not valid JSON');
  }
  if (sa?.type !== 'service_account') {
    throw new Error('JSON must be a Firebase service account (type: "service_account")');
  }
  if (!sa.project_id || !sa.client_email || !sa.private_key) {
    throw new Error('Invalid service account — needs project_id, client_email, and private_key');
  }
  if (/your[-_]?gcp|your[-_]?project|placeholder|example\.com/i.test(sa.project_id)) {
    throw new Error('Service account project_id looks like a placeholder');
  }
  if (/your[-_]?service|placeholder|example\.com/i.test(sa.client_email)) {
    throw new Error('Service account client_email looks like a placeholder');
  }
  if (sa.private_key.includes('...') || sa.private_key.length < 400) {
    throw new Error('Service account private_key appears truncated or fake — paste the full key from Firebase');
  }
  if (sa.token_uri && !sa.token_uri.includes('oauth2.googleapis.com')) {
    throw new Error('token_uri must be https://oauth2.googleapis.com/token — use JSON downloaded from Firebase');
  }
  if (!/^[a-z0-9-]{4,40}$/.test(sa.project_id)) throw new Error('Service account project_id is not a valid Firebase project id');
  return sa as ServiceAccount;
}

const httpUrl = (v: unknown): string | undefined => {
  if (typeof v !== 'string' || !v.trim()) return undefined;
  const s = v.trim();
  if (s.startsWith('/')) {
    // Relative to the subscribing site. "//host" and "/\host" would leave it.
    return s.startsWith('//') || s.startsWith('/\\') ? undefined : s.slice(0, 2000);
  }
  try {
    const u = new URL(s);
    return u.protocol === 'https:' || u.protocol === 'http:' ? u.toString().slice(0, 2000) : undefined;
  } catch {
    return undefined;
  }
};
const text = (v: unknown, max: number) => (typeof v === 'string' ? v.slice(0, max) : '');

/** Clean user-supplied content: trims lengths, keeps only http(s)/relative URLs, max 2 actions. */
function normalizeContent(input: Record<string, unknown>): PushContent {
  const actions = Array.isArray(input.actions) ? (input.actions as PushAction[]) : [];
  const ttl = Number(input.ttl_seconds ?? input.ttlSeconds);
  return {
    title: text(input.title, 200),
    body: text(input.body, 1000),
    icon_url: httpUrl(input.icon_url ?? input.iconUrl),
    image_url: httpUrl(input.image_url ?? input.imageUrl),
    badge_url: httpUrl(input.badge_url ?? input.badgeUrl),
    tag: text(input.tag, 100) || undefined,
    click_url: httpUrl(input.click_url ?? input.clickAction ?? input.click_action),
    ttl_seconds: Number.isFinite(ttl) && ttl > 0 ? Math.min(Math.floor(ttl), 2419200) : 86400,
    actions: actions.slice(0, 2).map((a, i) => ({
      action: text(a?.action, 40) || `action_${i + 1}`,
      title: text(a?.title, 40) || 'Open',
      url: httpUrl(a?.url),
    })),
    track_clicks: input.track_clicks !== false && input.track_opens !== false && input.trackOpens !== false,
    require_interaction: input.require_interaction === true || input.requireInteraction === true,
  };
}

/** FCM rejects data payloads over 4,096 bytes. Keep a margin for FCM's own keys. */
const MAX_DATA_BYTES = 3_800;
const byteLen = (o: unknown) => new TextEncoder().encode(JSON.stringify(o)).length;

/** FCM v1 request body. Data values must all be strings. Oversized content is trimmed to
 *  fit (body first, then images, then button links) so a send never fails for size. */
function buildFcmMessage(token: string, content: PushContent, ctx: PushContext) {
  const msg = buildFcmMessageRaw(token, content, ctx);
  const data = msg.message.data;
  if (byteLen(data) <= MAX_DATA_BYTES) return msg;
  const over = () => byteLen(data) > MAX_DATA_BYTES;
  if (over()) {
    const excess = byteLen(data) - MAX_DATA_BYTES;
    const body = data.body;
    data.body = body.slice(0, Math.max(0, body.length - excess - 1)) + (body ? '…' : '');
  }
  for (const k of ['image_url', 'badge_url', 'icon_url'] as const) if (over()) data[k] = '';
  if (over()) {
    const actions = (JSON.parse(data.actions_json) as PushAction[]).map((a) => ({ ...a, url: undefined }));
    data.actions_json = JSON.stringify(actions);
  }
  if (over()) data.actions_json = '[]';
  if (over()) data.delivery_name = '';
  return msg;
}

function buildFcmMessageRaw(token: string, content: PushContent, ctx: PushContext) {
  const data: Record<string, string> = {
    marbee: '1',
    message_id: ctx.message_id,
    tenant_id: ctx.tenant_id,
    environment: ctx.environment,
    journey_id: ctx.journey_id ?? '',
    delivery_id: ctx.delivery_id ?? '',
    delivery_name: ctx.delivery_name ?? '',
    title: content.title,
    body: content.body ?? '',
    icon_url: content.icon_url ?? '',
    image_url: content.image_url ?? '',
    badge_url: content.badge_url ?? '',
    tag: content.tag ?? '',
    click_url: content.click_url ?? '/',
    actions_json: JSON.stringify(content.actions ?? []),
    track_clicks: content.track_clicks === false ? 'false' : 'true',
    require_interaction: content.require_interaction ? 'true' : '',
    engage_url: ctx.engage_url ?? '',
  };
  return {
    message: {
      token,
      data,
      webpush: { headers: { TTL: String(content.ttl_seconds ?? 86400), Urgency: 'high' } },
    },
  };
}

type FcmErrorBody = { error?: { status?: string; message?: string; details?: Array<{ errorCode?: string }> } };

/** Map an FCM v1 HTTP response to what the outbox should do next. */
function classifyFcmResponse(status: number, bodyText: string, retryAfter?: string | null): SendResult {
  if (status >= 200 && status < 300) return { outcome: 'delivered', httpStatus: status };
  let parsed: FcmErrorBody = {};
  try { parsed = JSON.parse(bodyText); } catch { /* not JSON */ }
  const codes = (parsed.error?.details ?? []).map((d) => d?.errorCode).filter(Boolean) as string[];
  const st = parsed.error?.status ?? '';
  const msg = (parsed.error?.message ?? bodyText ?? '').slice(0, 300);
  const has = (c: string) => codes.includes(c) || st === c;
  const ra = retryAfter ? Number(retryAfter) : NaN;
  const retryAfterSeconds = Number.isFinite(ra) && ra > 0 ? Math.min(Math.floor(ra), 3600) : undefined;
  const error = `FCM ${status}${codes[0] || st ? ` ${codes[0] || st}` : ''}: ${msg}`.trim();

  if (status === 404 || status === 410 || has('UNREGISTERED')) return { outcome: 'invalid_token', error, httpStatus: status };
  if (has('SENDER_ID_MISMATCH')) return { outcome: 'invalid_token', error, httpStatus: status };
  if (status === 400 && /registration token/i.test(msg)) return { outcome: 'invalid_token', error, httpStatus: status };
  if (status === 429 || has('QUOTA_EXCEEDED')) return { outcome: 'retry', error, retryAfterSeconds: retryAfterSeconds ?? 60, httpStatus: status };
  if (status >= 500 || has('UNAVAILABLE') || has('INTERNAL')) return { outcome: 'retry', error, retryAfterSeconds, httpStatus: status };
  if (status === 401) return { outcome: 'retry', error, httpStatus: status }; // access token expired mid-run
  return { outcome: 'failed', error, httpStatus: status };
}

/** Human-readable hint for the settings page / delivery log. */
function explainFcmError(error: string): string {
  if (/UNAUTHENTICATED|THIRD_PARTY_AUTH_ERROR|invalid authentication|PERMISSION_DENIED/i.test(error)) {
    return 'Firebase rejected the server key. Re-download the service-account JSON (Firebase → Project settings → Service accounts) and make sure "Firebase Cloud Messaging API (V1)" is enabled.';
  }
  if (/SENDER_ID_MISMATCH/i.test(error)) {
    return 'This browser was subscribed with a different Firebase project than the server key. Check the web config and service account belong to the same project.';
  }
  if (/UNREGISTERED|registration token/i.test(error)) return 'The browser subscription has expired or was removed — the device was pruned.';
  return error;
}

// ---------------------------------------------------------------- OAuth
const tokenCache = new Map<string, { token: string; exp: number }>();

function base64Url(data: string | Uint8Array): string {
  const bytes = typeof data === 'string' ? new TextEncoder().encode(data) : data;
  let bin = '';
  for (let i = 0; i < bytes.length; i += 1) bin += String.fromCharCode(bytes[i]);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function pemToDer(pem: string): ArrayBuffer {
  const b64 = pem.replace(/-----(BEGIN|END) PRIVATE KEY-----/g, '').replace(/\\n/g, '').replace(/\s/g, '');
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i += 1) out[i] = bin.charCodeAt(i);
  return out.buffer;
}

/** Google access token for FCM, cached per service account for ~50 minutes. */
async function getFcmAccessToken(sa: ServiceAccount, opts: { fetchFn?: typeof fetch; force?: boolean } = {}): Promise<string> {
  const now = Math.floor(Date.now() / 1000);
  const cached = tokenCache.get(sa.client_email);
  if (!opts.force && cached && cached.exp - 600 > now) return cached.token;

  const header = base64Url(JSON.stringify({ alg: 'RS256', typ: 'JWT' }));
  const claim = base64Url(JSON.stringify({
    iss: sa.client_email,
    scope: 'https://www.googleapis.com/auth/firebase.messaging',
    aud: 'https://oauth2.googleapis.com/token',
    iat: now,
    exp: now + 3600,
  }));
  const key = await crypto.subtle.importKey('pkcs8', pemToDer(sa.private_key), { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' }, false, ['sign']);
  const sig = new Uint8Array(await crypto.subtle.sign('RSASSA-PKCS1-v1_5', key, new TextEncoder().encode(`${header}.${claim}`)));
  const jwt = `${header}.${claim}.${base64Url(sig)}`;

  const res = await (opts.fetchFn ?? fetch)('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: `grant_type=${encodeURIComponent('urn:ietf:params:oauth:grant-type:jwt-bearer')}&assertion=${jwt}`,
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || !data.access_token) {
    // Never echo the response wholesale (could include request details); keep the error code.
    throw new Error(`Google OAuth failed: ${String(data.error ?? res.status)}${data.error_description ? ` — ${String(data.error_description).slice(0, 200)}` : ''}`);
  }
  tokenCache.set(sa.client_email, { token: data.access_token, exp: now + Number(data.expires_in ?? 3600) });
  return data.access_token;
}

function forgetFcmAccessToken(sa: ServiceAccount): void {
  tokenCache.delete(sa.client_email);
}

/** Send one message. Never throws — network errors come back as a retry. */
async function sendFcm(
  sa: ServiceAccount,
  token: string,
  content: PushContent,
  ctx: PushContext,
  opts: { fetchFn?: typeof fetch } = {},
): Promise<SendResult> {
  const f = opts.fetchFn ?? fetch;
  try {
    const access = await getFcmAccessToken(sa, opts);
    const res = await f(`https://fcm.googleapis.com/v1/projects/${sa.project_id}/messages:send`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${access}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(buildFcmMessage(token, content, ctx)),
      signal: AbortSignal.timeout(15000),
    });
    const result = classifyFcmResponse(res.status, res.ok ? '' : await res.text(), res.headers.get('retry-after'));
    if (res.status === 401) forgetFcmAccessToken(sa);
    return result;
  } catch (e) {
    const m = e instanceof Error ? e.message : String(e);
    // A bad key is not going to fix itself on retry.
    if (/Google OAuth failed: (invalid_grant|invalid_client|unauthorized_client)/.test(m) || /pkcs8|DataError|import/i.test(m)) {
      return { outcome: 'failed', error: m };
    }
    return { outcome: 'retry', error: `Network: ${m}`.slice(0, 300) };
  }
}

// ---------------------------------------------------------------- provider key
type MinimalClient = {
  // deno-lint-ignore no-explicit-any
  from: (t: string) => any;
};

/**
 * Load a provider's service-account JSON from the server-only secrets table (sql/95),
 * re-sealing legacy plaintext on the way. Falls back to the pre-95 column so a deploy
 * of the functions before the SQL keeps working.
 */
async function loadServiceAccountJson(
  supabase: MinimalClient,
  provider: { id: string; tenant_id?: string; credentials_encrypted?: string | null },
  box: { openSecret: (s: string) => Promise<string | null>; sealSecret: (s: string) => Promise<string>; isSealed: (s: string) => boolean },
): Promise<string | null> {
  let q = supabase.from('channel_provider_secrets').select('secret').eq('provider_id', provider.id);
  if (provider.tenant_id) q = q.eq('tenant_id', provider.tenant_id); // defence in depth
  const { data, error } = await q.maybeSingle();
  if (!error && data?.secret) {
    const plain = await box.openSecret(data.secret);
    if (plain && !box.isSealed(data.secret)) {
      try {
        const sealed = await box.sealSecret(plain);
        await supabase.from('channel_provider_secrets').update({ secret: sealed, updated_at: new Date().toISOString() }).eq('provider_id', provider.id);
      } catch (e) {
        console.error('re-seal of web push key skipped', e instanceof Error ? e.message : e);
      }
    }
    return plain;
  }
  const legacy = provider.credentials_encrypted?.trim();
  return legacy && legacy !== '{}' ? legacy : null;
}

/** Backoff used by the outbox (mirrors complete_web_push in sql/95, for display/tests). */
function backoffSeconds(attempt: number, retryAfter?: number): number {
  return Math.min(Math.max(30 * 4 ** Math.max(attempt - 1, 0), retryAfter ?? 0), 3600);
}

// ---- push-worker/index.ts ------------------------------------
// push-worker — drains the Web Push outbox (sql/95, D-022).
//
// Called ONLY with PUSH_WORKER_SECRET (or the service-role key): by pg_cron every minute (push_worker_tick →
// Vault push_worker_url / push_worker_key) and right after something is queued
// (enqueue_web_push → push_worker_kick). Claims batches with SKIP LOCKED, so several
// overlapping runs never send the same row twice. Each row's outcome is recorded by
// complete_web_push(): delivered · retry with backoff · invalid token (device pruned)
// · failed. Runs for at most ~45 s per call.
//
// Deploy with "Enforce JWT Verification" OFF (pg_net calls it with the service key;
// the key is checked in code).


// D-024 throughput: claim 250 at a time, 25 FCM calls in flight, record a batch's outcomes in
// one database call, stop after MAX_PER_RUN and re-start itself while work remains. Runs are
// kept SMALL: Supabase allows ~2 s of CPU per invocation and kills bigger runs with HTTP 546
// (measured on dev 2026-11-27 with 3,000-push runs). Parallelism comes from more runs instead:
// a send starts one worker per ~1,000 pushes (max 10) and pg_cron tops up every minute.
const BATCH = 250;
const MAX_PER_RUN = 500;

/** Cron / pg_net callers present PUSH_WORKER_SECRET (a dedicated random secret, also stored
 *  in Vault as push_worker_key). The service-role key is accepted too. */
function isWorkerCaller(req: Request): boolean {
  if (isServiceCaller(req)) return true;
  const secret = Deno.env.get('PUSH_WORKER_SECRET') ?? '';
  const header = req.headers.get('authorization') ?? '';
  const token = header.startsWith('Bearer ') ? header.slice(7).trim() : '';
  return secret.length >= 32 && token.length > 0 && constantTimeEqual(token, secret);
}
const CONCURRENCY = 25;
const BUDGET_MS = 25_000;

type Outcome = { id: string; outcome: SendResult['outcome']; error: string | null; retry_after: number | null };

type Row = {
  id: string; tenant_id: string; environment: string; message_id: string; content: Record<string, unknown>;
  journey_id: string | null; delivery_id: string | null; delivery_name: string | null; provider_id: string | null;
  fcm_token: string; attempts: number;
};

async function runPool<T>(items: T[], size: number, fn: (item: T) => Promise<void>) {
  let i = 0;
  const workers = Array.from({ length: Math.min(size, items.length) }, async () => {
    while (i < items.length) {
      const item = items[i++];
      await fn(item);
    }
  });
  await Promise.all(workers);
}

serve(async (req) => {
  if (req.method !== 'POST') return errorResponse('Method not allowed', 405);
  if (!isWorkerCaller(req)) return errorResponse('Unauthorized', 401);

  const supabase = getServiceClient();
  const engageUrl = `${(Deno.env.get('SUPABASE_URL') ?? '').replace(/\/$/, '')}/functions/v1/push-engage`;
  const providers = new Map<string, Promise<{ sa?: ServiceAccount; error?: string; transient?: boolean }>>();
  const started = Date.now();
  const totals = { claimed: 0, delivered: 0, retry: 0, invalid_token: 0, failed: 0 };

  const providerFor = (row: Row) => {
    const key = `${row.tenant_id}|${row.environment}|${row.provider_id ?? 'default'}`;
    if (!providers.has(key)) {
      providers.set(key, (async () => {
        let q = supabase.from('channel_providers').select('id, tenant_id, credentials_encrypted, status')
          .eq('tenant_id', row.tenant_id).eq('environment', row.environment).eq('channel', 'web_push');
        q = row.provider_id ? q.eq('id', row.provider_id) : q.eq('is_default', true);
        const { data, error } = await q.limit(1).maybeSingle();
        if (error) return { error: `Provider lookup failed: ${error.message}`, transient: true };
        if (!data) return { error: 'No default Web Push (Firebase) provider for this environment — add one in Channels → Web Push' };
        if (data.status && data.status !== 'active') return { error: 'The Web Push provider is disabled' };
        try {
          const raw = await loadServiceAccountJson(supabase, data, { openSecret, sealSecret, isSealed });
          if (!raw) return { error: 'Firebase service-account JSON is not configured (Channels → Web Push)' };
          return { sa: parseServiceAccount(raw) };
        } catch (e) {
          const m = e instanceof Error ? e.message : String(e);
          return { error: m, transient: /MARBEE_SECRETS_KEY/.test(m) };
        }
      })());
    }
    return providers.get(key)!;
  };

  // One database call per batch; falls back to one call per row (e.g. before sql/96 runs).
  const record = async (outcomes: Outcome[]) => {
    if (!outcomes.length) return;
    const { error } = await supabase.rpc('complete_web_push_batch', { p_results: outcomes });
    if (!error) return;
    console.error('complete_web_push_batch failed, recording row by row', error.message);
    await runPool(outcomes, 10, async (o) => {
      const { error: cErr } = await supabase.rpc('complete_web_push', {
        p_id: o.id, p_outcome: o.outcome, p_error: o.error, p_retry_after_seconds: o.retry_after,
      });
      // If this fails too, the row's lock expires and it is retried — at-least-once.
      if (cErr) console.error('complete_web_push failed', o.id, cErr.message);
    });
  };

  try {
    let hitCap = false;
    while (Date.now() - started < BUDGET_MS) {
      if (totals.claimed >= MAX_PER_RUN) { hitCap = true; break; }
      const { data, error } = await supabase.rpc('claim_web_push_batch', { p_limit: Math.min(BATCH, MAX_PER_RUN - totals.claimed) });
      if (error) {
        console.error('claim_web_push_batch failed', error.message);
        return errorResponse('Could not claim work', 500);
      }
      const batch = (data ?? []) as Row[];
      if (!batch.length) break;
      totals.claimed += batch.length;

      const outcomes: Outcome[] = [];
      await runPool(batch, CONCURRENCY, async (row) => {
        let result: SendResult;
        const prov = await providerFor(row);
        if (!prov.sa) {
          result = { outcome: prov.transient ? 'retry' : 'failed', error: prov.error };
        } else {
          result = await sendFcm(prov.sa, row.fcm_token, normalizeContent(row.content ?? {}), {
            message_id: row.message_id,
            tenant_id: row.tenant_id,
            environment: row.environment,
            journey_id: row.journey_id,
            delivery_id: row.delivery_id,
            delivery_name: row.delivery_name,
            engage_url: engageUrl,
          });
        }
        totals[result.outcome] += 1;
        outcomes.push({
          id: row.id,
          outcome: result.outcome,
          error: result.error ? explainFcmError(result.error).slice(0, 500) : null,
          retry_after: result.retryAfterSeconds ?? null,
        });
      });
      await record(outcomes);
      if (batch.length < BATCH && totals.claimed < MAX_PER_RUN) break;
    }

    // More due work than this run may take: start a replacement worker now instead of
    // waiting for the next cron minute (keeps a large blast draining continuously).
    let restarted = false;
    if (hitCap || Date.now() - started >= BUDGET_MS) {
      const { data: due } = await supabase.rpc('web_push_due_count');
      if (Number(due ?? 0) > 0) {
        const { data: kicked } = await supabase.rpc('push_worker_kick');
        restarted = kicked === true;
      }
    }
    return jsonResponse({ ok: true, ...totals, restarted, ms: Date.now() - started });
  } catch (e) {
    console.error('push-worker unhandled', e instanceof Error ? e.message : e);
    return errorResponse('Internal error', 500);
  }
});
